'use strict';
// Approved comparison experience. Real account records; explicitly scoped device-local working notes.
const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy = value => JSON.parse(JSON.stringify(value));
const today = () => new Date().toLocaleDateString('en-CA');
let storageOK=true;const serverRecords=new Map();
const E=DecisionEngine;
const A=AttentionEngine;
function notesKey(){return 'vantage-comparison-notes-v1:'+state.userId;}
function cacheNotes(){try{localStorage.setItem(notesKey(),JSON.stringify({version:1,decisions:Object.fromEntries(state.decisions.map(d=>[d.id,{stamp:d.updated_at,support:d.support||{}}])),sessionLinks:state.sessionLinks||{}}));storageOK=true;}catch{storageOK=false;}}
function coreFields(d){return {title:d.title,description:d.description||null,known_context:d.known_context||null,open_questions:d.open_questions||null,deadline:d.deadline||null,alternatives_considered:copy(options(d)),status:d.status,rationale:d.rationale||'',actual_outcome:d.actual_outcome||null};}
async function saveLocal(){for(const d of state.decisions){const base=serverRecords.get(d.id);if(!base)continue;const current=coreFields(d),before=coreFields(base),input={};for(const k of Object.keys(current))if(JSON.stringify(current[k])!==JSON.stringify(before[k]))input[k]=current[k];if(!Object.keys(input).length)continue;try{const saved=await command('update-decision',{id:d.id,expectedUpdatedAt:base.updated_at,input});Object.assign(d,saved);serverRecords.set(d.id,copy(saved));}catch(error){cacheNotes();throw new Error(error.message+' The account change is not confirmed. Keep this page open or refresh before retrying.');}}cacheNotes();if(!storageOK)toast('Working notes could not be kept in this browser. Account records are still available.');}
const dateText = value => value && !Number.isNaN(Date.parse(value)) ? new Date(value.length===10 ? value+'T12:00:00' : value).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}) : 'Not set';
const uuid = () => crypto.randomUUID();
const paths = {arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',spark:'m12 3 2.2 6.8L21 12l-6.8 2.2L12 21l-2.2-6.8L3 12l6.8-2.2Z',signal:'M2 12h5l3-8 4 16 3-8h5',plus:'M12 5v14M5 12h14',source:'M5 3h14v18H5zM9 8h6m-6 4h6m-6 4h4',clock:'M12 8v5l3 2M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',chevron:'m9 5 7 7-7 7'};
const icon = name => `<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.arrow}"/></svg>`;
const button = (label, action, id='', cls='') => `<button type="button" class="btn ${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
let state, busy=false, streaming=false, streamAbort=null, toastTimer, context=null, session=null;
const ui={view:'today',id:null,filter:'active',query:'',signals:'all',signalQuery:'',pane:'decision',selected:{},draft:'',chatError:'',local:{theme:'light',size:'normal',motion:'system',watch:[],dismiss:[]}};
const dialog=$('#dialog');
const decision=id=>state?.decisions.find(d=>d.id===id);
const signal=id=>state?AttentionEngine.events(state.signals).find(s=>s.id===id||s.memberIds.includes(id)):null;
const strategy=id=>state?.strategies.find(s=>s.id===id);
const options=d=>Array.isArray(d?.alternatives_considered)?d.alternatives_considered:[];
const choice=d=>options(d).find(o=>o.comparisonChoice)?.comparisonChoice;
const chosen=d=>options(d).find(o=>o.comparisonChoice);
const reviewDue=d=>E.due(d,today());
const stage=d=>d.status==='archived'?'Archived':d.actual_outcome?'Reviewed':reviewDue(d)?'Review due':d.status==='decided'?'Choice recorded':'Thinking it through';
const title=o=>o?.title||o?.description||'Untitled option';
const safeURL=value=>{try{const u=new URL(value);return /^https?:$/.test(u.protocol)?u.href:'';}catch{return '';}};
const block=text=>String(text||'').split(/\n\s*\n/).map(p=>`<p>${esc(p).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>')}</p>`).join('');
function toast(text){if(!storageOK&&/saved|recorded/i.test(text))text+=' Working notes could not be retained in this browser.';$('#toast').innerHTML='<span>'+esc(text)+'</span>';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').innerHTML='',7000);}
function show(title,body){if(dialog.open)dialog.close();$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;dialog.showModal();}
function close(){dialog.close();}
function go(hash){close();if(location.hash==='#'+hash)route();else location.hash=hash;}
function preferenceKey(){return 'vantage-comparison-preferences:'+state.userId;}
function savePreferences(){try{localStorage.setItem(preferenceKey(),JSON.stringify(ui.local));}catch{toast('This browser could not retain the preference.');}}
function applyPreferences(){document.documentElement.dataset.theme=ui.local.theme;document.documentElement.dataset.size=ui.local.size;document.documentElement.dataset.motion=ui.local.motion;}


async function request(url,method='GET',body){const res=await fetch(url,{method,cache:'no-store',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});let data;try{data=await res.json();}catch{throw new Error('VANTAGE did not return a readable response. Please try again.');}if(!res.ok){if(res.status===401)throw new Error('Your session expired. Sign in again in the current design, then refresh this page.');throw new Error(data.error||'Could not complete this action.');}return data;}
const command=(operation,input)=>request('/api/test/workspace','POST',{operation,...input});
async function run(work){if(busy){toast('Please finish the current action first.');return;}busy=true;const before=state?copy(state.decisions):null;document.body.setAttribute('aria-busy','true');$('#form-error')?.remove();try{await work();}catch(error){if(before&&state){state.decisions=before;cacheNotes();}const message=error.message||'Could not complete that action.';if(dialog.open){const node=document.createElement('p');node.id='form-error';node.className='form-error';node.setAttribute('role','alert');node.tabIndex=-1;node.textContent=message;$('#dialog-body').prepend(node);node.focus();}else toast(message);}finally{busy=false;streaming=false;document.body.removeAttribute('aria-busy');document.querySelectorAll('button[data-pending]').forEach(b=>{b.disabled=false;b.removeAttribute('data-pending');});}}
async function load(initial=false){const incoming=await request('/api/test/workspace');let notes={};try{notes=JSON.parse(localStorage.getItem('vantage-comparison-notes-v1:'+incoming.userId)||'{}');}catch{storageOK=false;}state=incoming;state.context=state.context||{};state.sessions=state.sessions||[];state.sessionLinks=notes.sessionLinks||{};state.analysis=state.analysis||{};for(const d of state.decisions){const cached=notes.decisions?.[d.id];d.support=copy(cached?.support||{evidence:[],thread:[],reviews:[]});if(cached&&cached.stamp!==d.updated_at){d.support.stale=true;d.support.snapshot=null;if(d.status==='open')for(const o of options(d))o.needsReview=true;}d.alternatives_considered=options(d).map((o,i)=>({...o,id:o.id||'existing-'+i}));serverRecords.set(d.id,copy(d));}state.signals=state.signals.map(s=>enrichSignal(s));if(initial){try{ui.local={...ui.local,...JSON.parse(localStorage.getItem(preferenceKey())||'{}')};}catch{storageOK=false;}ui.local.watch=Array.isArray(ui.local.watch)?ui.local.watch:[];ui.local.dismiss=Array.isArray(ui.local.dismiss)?ui.local.dismiss:[];ui.local.ack=ui.local.ack||{};ui.local.watchBaseline=ui.local.watchBaseline||{};for(const e of A.events(state.signals))if(ui.local.watch.includes(e.id)&&!ui.local.watchBaseline[e.id])ui.local.watchBaseline[e.id]=A.revision(e);}applyPreferences();render();}
function enrichSignal(s){const analysis=state.analysis?.[s.id]||{};return {...s,eventId:s.eventId||s.id,reports:s.reports||[{id:s.id,source:safeURL(s.url)?new URL(safeURL(s.url)).hostname:s.source==='manual'?'Saved source record':s.source==='rss'?'Saved RSS report':'Saved external report',url:s.url,publishedAt:s.published_at,claim:s.content,kind:'External source',availability:'saved-record',limit:'Saved external reporting. Check the original source and your actual exposure.'}],implication:analysis.soWhat||s.why_it_matters,ifAct:analysis.ifYouAct||'',ifWait:analysis.ifYouDont||'',nextCheck:analysis.immediateAction||s.what_to_consider||'',uncertainty:s.uncertainty||'The interpretation has not established your actual exposure or customer response. Source availability and coverage are not reported.',interpretedAt:analysis.createdAt||null,checkedAt:null};}
function notice(key){return state.errors[key]?`<div class="storage-notice" role="alert">${esc(state.errors[key])} ${button('Try again','refresh')}</div>`:'';}
function heading(h,p,action=''){return `<header class="page-head"><div><h1>${esc(h)}</h1><p>${esc(p)}</p></div>${action}</header>`;}
function empty(h,p){return `<section class="empty"><h2>${esc(h)}</h2><p>${esc(p)}</p></section>`;}
function back(hash,label){return `<a class="back" href="#${hash}">${icon('back')}${esc(label)}</a>`;}
function contextName(){return context?.kind==='decision'?decision(context.id)?.title:context?.kind==='signal'?signal(context.id)?.title:context?.kind==='strategy'?strategy(context.id)?.title:null;}
async function route(){const parts=location.hash.slice(1).split('/');const prior=ui.id;ui.view=parts[0]||'today';ui.id=parts[1]||null;if(!['today','decisions','signals','advisor','company','settings','strategies'].includes(ui.view))ui.view='today';if(ui.view==='advisor'){if(parts[2]&&parts[3]&&['decision','signal','strategy'].includes(parts[2]))context={kind:parts[2],id:parts[3]};else if(parts[1]!=='new')context=null;if(ui.id&&ui.id!=='new'&&(session?.id!==ui.id||!Array.isArray(session?.messages))){try{renderLoading();session=await request('/api/advisor/sessions/'+ui.id);const link=state.sessionLinks[ui.id];if(!parts[2]&&link)context=link;}catch(error){ui.chatError=error.message;session=null;}}if(!ui.id||ui.id==='new')session=null;}if(prior!==ui.id)ui.pane='decision';if(state)render();window.scrollTo({top:0,behavior:'instant'});$('#content').focus({preventScroll:true});}
function renderLoading(){ $('#content').innerHTML=empty('Opening the conversation…','Loading your saved messages.'); }
function render(){if(!state)return;applyPreferences();$('#company-name').textContent=state.profile.company_name||'Your workspace';$('#company-avatar').textContent=(state.profile.company_name||'V').slice(0,1).toUpperCase();const current=['strategies','decisions'].includes(ui.view)?'decisions':ui.view==='signals'?'signals':ui.view==='today'?'today':null;document.querySelectorAll('[data-nav]').forEach(a=>a.setAttribute('aria-current',a.dataset.nav===current?'page':'false'));$('#ask-advisor-link').setAttribute('aria-current',ui.view==='advisor'?'page':'false');let html=ui.view==='today'?todayView():ui.view==='signals'?(ui.id?signalView(signal(ui.id)):signalsView()):ui.view==='decisions'?(ui.id?decisionView(decision(ui.id)):decisionsView()):ui.view==='strategies'?(ui.id?strategyView(strategy(ui.id)):strategiesView()):ui.view==='advisor'?advisorView():ui.view==='company'?companyView():settingsView();$('#content').innerHTML=html;const input=$('#advisor-question');if(input)input.value=ui.draft;}
function decisionsView(){const active=state.decisions.filter(d=>d.status!=='archived'&&!d.actual_outcome),past=state.decisions.filter(d=>d.status==='archived'||d.actual_outcome);const rows=(ui.filter==='past'?past:ui.filter==='due'?state.decisions.filter(reviewDue):active).filter(d=>d.title.toLowerCase().includes(ui.query.toLowerCase()));return `${heading('My decisions.','Every question, your reasoning, the choice and what happened next.',button('Start a question '+icon('plus'),'create'))}${notice('decisions')}<div class="list-controls"><div class="tabs" aria-label="Decision views">${[['active','Active'],['past','Past'],['due','Review due']].map(([value,label])=>`<button data-action="filter" data-id="${value}" aria-selected="${ui.filter===value}">${label}</button>`).join('')}<a href="#strategies">Strategies <span class="count">${state.strategies.length}</span></a></div><label class="list-search"><span class="sr-only">Search decisions</span><input id="decision-search" type="search" placeholder="Find a decision" value="${esc(ui.query)}"></label></div><div>${rows.map(d=>`<a class="work-row" href="#decisions/${d.id}"><div><h2>${esc(d.title)}</h2><p>${esc(d.open_questions||d.description||d.rationale||'An open question.')}</p></div><div class="row-state">${stage(d)}<span>${d.deadline?'Deadline '+dateText(d.deadline):'No decision date set'}</span></div>${icon('chevron')}</a>`).join('')||empty('No decisions here yet.','Start with a question when you have a choice to weigh.')}</div>`;}
function sourceFor(d){if(d.source==='signal')return signal(d.source_id);if(d.source==='strategy')return strategy(d.source_id);return null;}
function strategiesView(){return `${back('decisions','My decisions')}${heading('Your strategies.','Saved approaches, their time horizons and what happened next.')}${notice('strategies')}${state.strategies.map(s=>`<a class="work-row" href="#strategies/${s.id}"><div><h2>${esc(s.title)}</h2><p>${esc(s.description)}</p></div><span class="badge">${esc(s.status)}</span>${icon('chevron')}</a>`).join('')||empty('No strategies saved yet.','Explore a signal to draft a strategy, or continue an existing approach.')}`;}
function strategyView(s){if(!s)return empty('Strategy unavailable.','Return to your saved strategies.');return `<article class="reader">${back('strategies','Your strategies')}<span class="badge">${esc(s.status)}</span><h1>${esc(s.title)}</h1>${block(s.description)}${s.signal_id&&signal(s.signal_id)?`<a class="text-link" href="#signals/${s.signal_id}">Connected signal ${icon('arrow')}</a>`:''}${[['Next 30 days',s.timeline_30d],['Next 90 days',s.timeline_90d],['Six months and beyond',s.timeline_6m],['Cost of inaction',s.cost_of_inaction]].filter(([,v])=>v).map(([h,v])=>`<section class="reader-section"><h2>${h}</h2>${block(v)}</section>`).join('')}<section class="reader-section"><h2>Work through this approach</h2><div class="reader-actions">${button('Ask Advisor','strategy-ask',s.id)}${button('Develop as a decision','strategy-develop',s.id,'primary')}</div><form data-form="strategy-status" data-id="${s.id}" class="form-stack"><label><span>Strategy stage</span><select name="status">${['considering','deciding','decided','archived'].map(v=>`<option ${s.status===v?'selected':''}>${v}</option>`).join('')}</select></label><button class="btn" type="submit">Save stage</button></form></section>${s.outcome_status?`<section class="reader-section"><h2>Outcome</h2><p>${esc(s.outcome_status.replace(/_/g,' '))}</p>${block(s.outcome_notes)}</section>`:s.status==='decided'?`<section class="reader-section"><h2>What happened?</h2><form data-form="strategy-outcome" data-id="${s.id}" class="form-stack"><label><span>Result</span><select name="outcome_status"><option value="worked">Worked</option><option value="didnt_work">Did not work</option><option value="too_early">Too early</option><option value="unclear">Unclear</option></select></label><label><span>What did you observe?</span><textarea name="outcome_notes" maxlength="8000" required></textarea></label><button class="btn primary" type="submit">Record outcome</button></form></section>`:''}</article>`;}
function cleanReply(text){return String(text||'').split('[[VANTAGE_MEMORY]]')[0].trim();}
function messagesView(){return (session?.messages||[]).map(m=>m.role==='user'?`<div class="user-message">${esc(m.content)}</div>`:`<article class="assistant-message"><div class="answer-origin">Advisor response · check claims</div>${block(cleanReply(m.content))}</article>`).join('');}
function advisorView(){return `<div class="advisor-page">${heading('Advisor.','A place to understand, explore and challenge your thinking.',button('New conversation '+icon('plus'),'new-chat'))}${notice('sessions')}<div class="advisor-toolbar"><label for="conversation-picker">Your conversations</label><select id="conversation-picker"><option value="">Start a new conversation</option>${state.sessions.map(s=>`<option value="${s.id}" ${session?.id===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select>${button('Context in use','context','','ghost small')}</div><div class="conversation-scope"><span class="badge">Conversation</span><p>Conversations are saved to your account. A conversation is not a decision.</p></div>${contextName()?`<div class="advisor-source-line">About ${esc(context.kind)}<strong>${esc(contextName())}</strong></div>`:''}${ui.chatError?`<div class="storage-notice" role="alert">${esc(ui.chatError)}</div>`:''}<section class="advisor-thread" aria-label="Advisor conversation"><div id="chat-messages">${session?.messages?.length?messagesView():`<div class="advisor-welcome">${icon('spark')}<h2>What would you like to understand?</h2><p>Explore a concern, challenge an assumption or consider a direction. There is no need to decide yet.</p><p class="muted">Your account context and this conversation are available to Advisor. Check important claims against their sources.</p></div>`}</div><div id="stream-state" role="status">${streaming?'Advisor is responding…':''}</div></section><form data-form="advisor" class="general-composer"><label class="sr-only" for="advisor-question">Ask Advisor</label><textarea id="advisor-question" name="question" maxlength="5000" required placeholder="What is on your mind?" ${streaming?'disabled':''}></textarea><div class="composer-footer"><span>AI can be wrong · check important claims</span>${streaming?button('Stop','stop'): '<button type="submit" class="btn primary">Ask '+icon('arrow')+'</button>'}</div></form>${session?.messages?.length?`<div class="develop-bar"><div><strong>Is there a choice to weigh?</strong><p>Keep exploring, or start an open decision.</p></div>${context?.kind==='decision'?`<a class="btn" href="#decisions/${context.id}">Open this decision ${icon('arrow')}</a>`:button('Develop as a decision '+icon('arrow'),'develop-chat')}</div>`:''}</div>`;}

function companyView(){const p=state.profile,c=state.context||{};return `<article class="reader">${back('today','Today')}${heading('Your company.','The context behind the guidance.',button('Edit context','company-edit'))}${notice('context')}<section class="reader-section"><h2>${esc(p.company_name||'Your company')}</h2>${block(c.product_description||'Your product description is not recorded yet.')}</section>${[['Who buys',c.target_customer],['Current focus',c.top_priority_other||c.top_priority],['Business model',c.revenue_model||p.business_model],['Revenue range you supplied',p.revenue_range],['Additional context',c.additional_context]].map(([h,v])=>`<section class="reader-section"><h2>${h}</h2>${block(v||'Not recorded.')}</section>`).join('')}<p class="footer-note">Supplied context is not independently verified. <a href="/profile">Open all company settings in the current design</a>.</p></article>`;}
function legacyFields(values={}){return `<label><span>Your question</span><input name="title" required maxlength="120" value="${esc(values.title||'')}"></label><label><span>Why does this matter now?</span><textarea name="description" maxlength="12000">${esc(values.description||'')}</textarea></label><label><span>What do you know?</span><textarea name="known_context" maxlength="12000">${esc(values.known_context||'')}</textarea></label><label><span>What could change your mind?</span><textarea name="open_questions" maxlength="12000">${esc(values.open_questions||'')}</textarea></label><label><span>Deadline, if needed</span><input name="deadline" type="date" value="${esc(values.deadline?.slice(0,10)||'')}"></label>`;}
function reviewDate(d){const r=d.support?.reviews||[],last=r[r.length-1];return last?.status==='too-early'?last.nextReview:d.support?.snapshot?.review||choice(d)?.review;}
function support(d){return d.support||(d.support={evidence:[],thread:[],reviews:[]});}
async function replaceLocal(d){const i=state.decisions.findIndex(x=>x.id===d.id);state.decisions[i]=d;await saveLocal();render();}
function field(label,name,value='',extra=''){return `<label><span>${esc(label)}</span><textarea name="${name}" maxlength="6000" ${extra}>${esc(value)}</textarea></label>`;}
function textField(label,name,value='',extra=''){return `<label><span>${esc(label)}</span><input name="${name}" value="${esc(value)}" ${extra.includes('maxlength=')?'':'maxlength="500"'} ${extra}></label>`;}
function formEnd(label='Save'){return `<div class="form-actions">${button('Cancel','close')}<button type="submit" class="btn primary">${label}</button></div>`;}
function engineAction(label,action,d,cls=''){return button(label,action,d.id,cls);}
function decisionView(d){
 if(!d)return empty('Decision unavailable.','Return to My decisions.');const s=support(d),list=options(d),selected=ui.selected[d.id]||null,diag=E.diagnose(d,selected),snap=s.snapshot,closed=d.status!=='open';
 return `${back('decisions','My decisions')}<p class="note-scope">Account: choices, options and outcomes. This browser: working notes and extra review history.</p>${support(d).stale?'<p class="storage-notice">This decision changed in another view. Recheck the browser notes before relying on them.</p>':''}<header class="work-heading"><div class="work-meta"><span class="badge ${reviewDue(d)?'attention':''}">${stage(d)}</span><div class="cluster">${!closed?engineAction('Edit question','edit',d,'ghost small'):''}${engineAction(d.status==='archived'?'Restore':'Archive',d.status==='archived'?'restore':'archive',d,'ghost small')}</div></div><h1>${esc(d.title)}</h1><p>${esc(d.description||'Keep the question open while you work it through.')}</p>${s.parentId?`<a class="text-link" href="#decisions/${s.parentId}">Review the original choice ${icon('arrow')}</a>`:''}</header><div class="mobile-pane-tabs" role="tablist" aria-label="Question workspace"><button data-action="pane" data-id="decision" role="tab" aria-selected="${ui.pane==='decision'}">Your decision</button><button data-action="pane" data-id="guidance" role="tab" aria-selected="${ui.pane==='guidance'}">Advisor</button></div><div class="work-layout ${ui.pane==='guidance'?'show-guidance':''}"><article class="decision-document">
 <section class="document-part decision-frame"><div class="section-heading"><h2>What a good outcome looks like</h2>${!closed?engineAction('Refine','frame',d,'ghost small'):''}</div><p class="overview-lead">${esc(s.goal||'What needs to improve? A sentence is enough.')}</p><div class="limit-line"><span>Keep within</span><p>${esc(s.limit||'No hard limit stated. You can leave this open.')}</p></div>${d.deadline?`<p class="small muted">Decision date · ${dateText(d.deadline)}</p>`:''}</section>
 ${closed?(snap?receiptView(d):legacyRecordedView(d)):''}
 <section class="document-part"><div class="section-heading"><h2>${closed?'Responses considered':'Compare your responses'}</h2>${!closed?engineAction('Add option','option',d,'ghost small'):''}</div><p class="section-note">${closed?'The responses kept with this record.':'Same goal. Different consequences. Nothing is selected for you.'}</p><div class="engine-options">${list.map(o=>`<article class="option ${selected===o.id?'selected':''}"><div class="option-title"><h3>${esc(title(o))}</h3>${!closed?`<label class="pick-option"><input type="radio" name="response" value="${esc(o.id)}" ${selected===o.id?'checked':''} aria-label="Consider ${esc(title(o))}"><span class="sr-only">Consider this option</span></label>`:''}</div>${block(o.detail||'')}${o.needsReview?'<p class="form-help">Goal or limit changed. Recheck this response.</p>':''}<dl class="comparison-pairs"><dt>Expected effect</dt><dd>${esc(o.expected||'Not assessed.')}</dd><dt>Downside</dt><dd>${esc(o.reasonRejected||'Not assessed.')}</dd><dt>Effort</dt><dd>${esc(o.effort||'Not assessed.')}</dd><dt>Your limit</dt><dd>${esc(o.fit==='within'?'Within limit · your assessment':o.fit==='outside'?'Outside limit · your assessment':'Not checked')}</dd><dt>Undoing it</dt><dd>${esc(o.reversibility==='easy'?'Easy to reverse · your assessment':o.reversibility==='hard'?'Hard to reverse · your assessment':'Not assessed.')}</dd></dl>${!closed?`<button class="text-link" data-action="edit-option" data-id="${d.id}" data-option="${esc(o.id)}">Edit response</button>`:''}</article>`).join('')||'<p class="empty-copy">Start with what you would keep doing, or one change you could make. Advisor can help frame the comparison.</p>'}</div>${!closed?`<details class="disclosure"><summary>What if you wait?</summary><div class="inside">${block(s.inaction||'The consequence of waiting has not been assessed. Do not assume waiting is free—or automatically wrong.')}<form data-form="inaction" data-id="${d.id}">${field('What could happen if you keep the current approach?','inaction',s.inaction||'')}<button class="btn" type="submit">Save the cost of waiting</button></form></div></details>`:''}</section>
 <section class="document-part"><div class="section-heading"><h2>What supports this?</h2>${!closed?engineAction('Add evidence','evidence',d,'ghost small'):''}</div>${evidenceList(s.evidence||[],d,!closed)}${d.known_context||d.open_questions?`<details class="disclosure"><summary>Context already saved to your account</summary><div class="inside">${d.known_context?`<h3>Saved context</h3>${block(d.known_context)}`:''}${d.open_questions?`<h3>Open questions</h3>${block(d.open_questions)}`:''}</div></details>`:''}${sourceFor(d)?`<div class="evidence-row"><span>External signal · not business proof</span><a class="text-link" href="#signals/${d.source_id}">Inspect the originating signal ${icon('arrow')}</a></div>`:''}</section>
 ${!closed?`<section class="document-part"><div class="section-heading"><h2>The next useful check</h2>${engineAction(s.learning?'Edit check':'Plan a check','learning',d,'ghost small')}</div>${s.learning?`<h3>${esc(s.learning.question)}</h3>${block(s.learning.check)}<p><strong>What would change your mind:</strong> ${esc(s.learning.trigger||'Still open.')}</p><p class="small muted">${s.learning.date?'Check '+dateText(s.learning.date)+'. ':''}A learning plan, not a recorded business choice.</p>`:`<p>When evidence is thin, choose what to learn before committing further. A test is useful only if it is safe, feasible and can distinguish the responses.</p>`}</section>`:''}
 ${s.calculationType==='pricing'?`<details class="document-part disclosure"><summary>Check a number · optional</summary><div class="inside">${scenarioView(d)}</div></details>`:''}
 ${!closed?`<section class="document-part choice-area"><h2>Your call</h2><p>${selected?'Considering: '+esc(title(diag.selected))+'. Selecting is not committing.':'Choose a response above when you want to record it.'}</p>${diag.warnings.length?`<details class="disclosure"><summary>Limits to keep in mind · ${diag.warnings.length}</summary><div class="inside">${diag.warnings.map(x=>`<p>${esc(x)}</p>`).join('')}</div></details>`:''}<button class="btn primary" data-action="record" data-id="${d.id}" ${selected?'':'disabled'}>Record choice ${icon('arrow')}</button><p class="form-help">You can proceed with unknowns. Record what you are accepting, not certainty you do not have.</p></section>`:''}
 </article>${contextualAdvisor(d)}</div>`;
}
function evidenceList(items,d,editable){return items.length?items.map(e=>`<div class="evidence-item"><div class="split"><span class="evidence-kind">${esc(e.kind==='business'?'Your business · supplied':e.kind==='external'?'External source':e.kind==='assumption'?'Assumption':'Unknown')}${e.decisive?' · could change this choice':''}</span>${editable?`<button class="text-link" data-action="evidence" data-id="${d.id}" data-evidence="${esc(e.id)}">Edit</button>`:''}</div><p>${esc(e.claim)}</p><span class="small muted">${esc(e.source||'Origin not supplied')}${e.date?' · '+dateText(e.date):''}</span>${e.url&&safeURL(e.url)?` <a class="text-link" target="_blank" rel="noopener" href="${esc(safeURL(e.url))}">Open source ↗</a>`:''}${e.limit?`<p class="form-help">${esc(e.limit)}</p>`:''}</div>`).join(''):'<p>No evidence attached. Add an observation, a source or the assumption that matters. A source label does not verify a claim.</p>';}
function receiptView(d){if(!support(d).snapshot)return legacyRecordedView(d);const s=support(d),c=s.snapshot,rs=s.reviews||[];return `<section class="document-part choice-area"><div class="part-label">YOUR RECORDED CHOICE · ${dateText(c.at)}</div><h2 class="choice-title">${esc(c.optionTitle)}</h2>${block(c.why)}<dl class="comparison-pairs"><dt>Expected</dt><dd>${esc(c.expected||'Not yet known.')}</dd><dt>Still uncertain</dt><dd>${esc(c.uncertainty||'No additional uncertainty recorded.')}</dd><dt>Next step</dt><dd>${esc(c.next)}</dd><dt>Revisit if</dt><dd>${esc(c.condition||'No condition recorded.')}</dd><dt>Check back</dt><dd>${c.review?dateText(c.review):'Not scheduled.'}</dd></dl>${d.status==='decided'?engineAction(rs.length?'Add a follow-up review':'Review what happened','outcome',d,'primary'):''}<details class="disclosure"><summary>Original reasoning & review history</summary><div class="inside"><h3>At the time</h3><p><strong>Result:</strong> ${esc(c.context.goal||'Not stated.')}</p><p><strong>Limit:</strong> ${esc(c.context.limit||'Not stated.')}</p>${evidenceList(c.context.evidence,d,false)}${rs.map(r=>`<section class="evidence-item"><h3>${r.status==='too-early'?'Too early to tell':'Observed result'} · ${dateText(r.at)}</h3><p>${esc(r.observed)}</p><p>Action taken: ${esc(r.executed)}. ${esc(r.learned)}</p>${r.nextReview?`<p>Next check: ${dateText(r.nextReview)}</p>`:''}</section>`).join('')||'<p>No outcome recorded yet.</p>'}</div></details>${d.status==='decided'?engineAction('Reconsider in a new decision','reconsider',d,'ghost'):''}${s.parentId?`<a class="text-link" href="#decisions/${s.parentId}">Original decision</a>`:''}</section>`;}
function scenarioView(d){if(d.status!=='open'){const r=support(d).snapshot?.context.scenario?.result;return r?.available?`<p>At the time: current ${r.current.toLocaleString()} / month; scenario ${r.proposed.toLocaleString()} / month; difference ${r.delta.toLocaleString()}; break-even ${r.breakEvenCustomers} customers.</p><p class="form-help">${esc(r.limitation)} Original assumptions are preserved. Reconsider in a new decision to change them.</p>`:'<p>No calculation was recorded when you chose.</p>';}const p=support(d).scenario||{};return `<p>Use this only for a pricing question. Enter your own assumptions; the calculation does not predict customer behavior.</p><form data-form="scenario" data-id="${d.id}" class="form-grid">${[['Current monthly price','currentPrice'],['Current customers','currentCustomers'],['Possible monthly price','newPrice'],['Customers at that price · assumption','newCustomers']].map(([label,k])=>`<label><span>${label}</span><input name="${k}" type="number" min="0" step="any" value="${esc(p[k]??'')}"></label>`).join('')}<button type="submit" class="btn">Calculate sensitivity</button></form>${p.result?`<div class="scenario-result">${p.result.available?`<p>Current: ${p.result.current.toLocaleString()} / month. Scenario: ${p.result.proposed.toLocaleString()} / month.</p><p>Difference: ${p.result.delta.toLocaleString()}. Break-even customers: ${p.result.breakEvenCustomers}.</p><p class="form-help">${esc(p.result.limitation)} Currency units are yours.</p>`:`<p>${esc(p.result.reason)}</p>`}</div>`:''}`;}
function contextualAdvisor(d){const s=support(d),messages=s.thread||[],check=E.diagnose(d,ui.selected[d.id]);return `<aside class="guidance" aria-label="Advisor for this question"><header class="guidance-head"><h2>${icon('spark')}Advisor</h2></header><div class="guidance-context"><strong>${esc(d.title)}</strong><span>One continuing conversation with this decision.</span></div><div class="conversation" id="decision-thread">${ui.chatError?`<p class="storage-notice" role="alert">${esc(ui.chatError)}</p>`:''}${messages.length?messages.map((m,i)=>m.role==='user'?`<div class="user-message">${esc(m.content)}</div>`:`<article class="assistant-message"><div class="answer-origin">Advisor response · check claims</div>${block(m.content)}${d.status==='open'?`<button class="text-link" data-action="save-reasoning" data-id="${d.id}" data-message="${i}">Use in this decision</button>`:''}</article>`).join(''):`<div class="guidance-intro"><span class="eyebrow">Next useful step · workflow check</span><h3>${esc(d.status==='open'?check.next.label:'Look back at the original reasoning.')}</h3><p>${esc(d.status==='open'?check.next.why:'Review the result against what you expected, while keeping the original choice intact.')}</p>${d.status==='open'&&check.next.action!=='compare'?engineAction(check.next.action==='frame'?'Clarify the result':check.next.action==='learning'?'Plan the next check':check.next.action==='option'?'Add a response':'Review and record',check.next.action,d,'primary'):''}<p class="form-help">A check of supplied fields, not a business verdict.</p></div><div class="prompts">${['What needs checking?','Show the context behind this.'].map((q,i)=>`<button data-action="context-prompt" data-id="${d.id}" data-mode="${i?'context':'gaps'}" data-question="${esc(q)}">${q}</button>`).join('')}</div>`}</div><form class="guidance-composer" data-form="context-ask" data-id="${d.id}"><label for="context-question">Keep a question with this decision</label><textarea name="question" id="context-question" required maxlength="5000" placeholder="What are you still unsure about?">${esc(ui.decisionDrafts?.[d.id]||'')}</textarea><div class="composer-footer"><span>AI can be wrong</span>${streaming?button('Stop','stop'):'<button type="submit" class="btn primary">Ask '+icon('arrow')+'</button>'}</div></form></aside>`;}

function chatContext(){if(context?.kind==='decision'){const d=decision(context.id);return 'Decision context supplied by the account and browser notes. Source labels do not verify claims. Do not treat an external report as private-company evidence.\n'+JSON.stringify(E.contextPacket(d));}if(context?.kind==='signal'){const s=signal(context.id);return 'External signal. Source URL has not been retrieved by this chat.\n'+JSON.stringify({title:s.title,...A.decisionContext(s),ifAct:s.ifAct,ifWait:s.ifWait,uncertainty:s.uncertainty});}if(context?.kind==='strategy'){const s=strategy(context.id);return 'Saved strategy: '+JSON.stringify(s);}return '';}
async function sendMessage(question){ui.chatError='';const currentContext=context?{...context}:null,d=currentContext?.kind==='decision'?decision(currentContext.id):null;let active=session;if(d){const id=support(d).sessionId;active=id?await request('/api/advisor/sessions/'+id):null;}if(!active){active=await request('/api/advisor/sessions','POST',{title:(contextName()||question).slice(0,180)});state.sessions.unshift({id:active.id,title:active.title,updated_at:active.updated_at});}if(active&&!Array.isArray(active.messages))active=await request('/api/advisor/sessions/'+active.id);session=active;const id=active.id;if(d)support(d).sessionId=id;if(currentContext)state.sessionLinks[id]=currentContext;active.messages=[...(active.messages||[]),{role:'user',content:question}];active=await command('save-session',{id,expectedUpdatedAt:active.updated_at,messages:active.messages});session=active;const packet=chatContext(),base=active.messages.map(({role,content})=>({role,content}));if(packet)base[base.length-1]={role:'user',content:packet+'\n\nMy question: '+question};if(d){support(d).thread=active.messages;ui.decisionDrafts={...ui.decisionDrafts,[d.id]:''};}else{ui.draft='';history.replaceState(null,'','#advisor/'+id+(currentContext?'/'+currentContext.kind+'/'+currentContext.id:''));ui.view='advisor';ui.id=id;}active.messages.push({role:'assistant',content:''});if(d)support(d).thread=active.messages;streaming=true;streamAbort=new AbortController();render();let reply='',completed=false;try{const response=await fetch('/api/advisor/chat',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:base}),signal:streamAbort.signal});if(!response.ok){const e=await response.json().catch(()=>({}));throw new Error(e.error||'Advisor could not respond. Please try again.');}if(!response.body)throw new Error('Advisor returned no response stream.');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {done,value}=await reader.read();buffer+=done?decoder.decode():decoder.decode(value,{stream:true});let end;while((end=buffer.indexOf('\n\n'))!==-1){const event=buffer.slice(0,end).replace(/\r/g,'');buffer=buffer.slice(end+2);for(const line of event.split('\n')){if(!line.startsWith('data:'))continue;const raw=line.slice(5).trim();if(raw==='[DONE]'){completed=true;continue;}let payload;try{payload=JSON.parse(raw);}catch{throw new Error('Advisor sent an unreadable response.');}if(payload.error)throw new Error(payload.error);if(payload.delta){reply+=payload.delta;active.messages[active.messages.length-1].content=reply;if((d&&ui.view==='decisions'&&ui.id===d.id)||(!d&&ui.view==='advisor'&&ui.id===id))render();}if(payload.memory?.ok===false)ui.chatError='Advisor could not save its proposed company-context update. Your existing context is unchanged.';}}if(done)break;}if(!completed)throw new Error('The response ended early. The text shown may be incomplete.');}catch(error){ui.chatError=error.name==='AbortError'?'Response stopped. Any text shown may be incomplete.':error.message;}finally{streaming=false;streamAbort=null;active.messages[active.messages.length-1].content=cleanReply(reply);if(!reply.trim())active.messages.pop();try{active=await command('save-session',{id,expectedUpdatedAt:active.updated_at,messages:active.messages});}catch(error){ui.chatError=(ui.chatError?ui.chatError+' ':'')+error.message;}if(session?.id===id)session=active;if(d)support(d).thread=copy(active.messages);const index=state.sessions.findIndex(s=>s.id===id);if(index>=0)state.sessions[index]={id,title:active.title,updated_at:active.updated_at};cacheNotes();render();}}
function questionForm(d=null,from=null){const first=session?.messages?.find(m=>m.role==='user')?.content||'';show(d?'Refine the question':'Start with the problem',`<form data-form="${d?'edit-decision':'create-decision'}" data-id="${d?.id||''}" data-source="${from?.kind||'manual'}" data-source-id="${from?.id||''}" data-allow-new="${Boolean(from?.allowNew)}" class="form-stack">${from?.kind==='signal'?`<div class="promotion-preview"><h3>What stays attached</h3><p>${from.reports.length} source ${from.reports.length===1?'record':'records'}, the possible effect and its caveat. They remain external claims and assumptions, not business facts.</p><details class="disclosure"><summary>Inspect the attached claims</summary><div class="inside">${evidenceList(A.decisionContext(from).evidence,{},false)}</div></details></div>`:''}${textField('What choice are you considering?','title',d?.title||from?.title||first.slice(0,120),'required maxlength="120"')}${field('Why does it matter now? · optional','description',d?.description||from?.description||first)}<details class="disclosure"><summary>Add a desired result or limit · optional</summary><div class="inside">${field('What needs to improve?','goal',support(d||{}).goal||'')}${field('What must not get worse?','limit',support(d||{}).limit||'')}</div></details>${from?.kind==='signal'?field('Suggested next check · edit or clear','suggestedCheck',from.nextCheck||''):''}<p class="form-help">Start an open question. You do not need a recommendation yet.</p>${formEnd(d?'Save question':'Start thinking')}</form>`);}
function frameForm(d){const s=support(d);show('What would make this worthwhile?',`<form data-form="frame" data-id="${d.id}" class="form-stack">${field('What needs to improve?','goal',s.goal||'')}${field('What must not get worse? · optional','limit',s.limit||'')}${textField('Decision date · optional','deadline',d.deadline||'','type="date"')}<p class="form-help">Use your words. Unknown is a useful answer. These fields do not create a readiness score.</p>${formEnd('Save the frame')}</form>`);}
function optionForm(d,id=null){const o=options(d).find(x=>x.id===id)||{};show(id?'Refine this response':'One possible response',`<form data-form="option" data-id="${d.id}" data-option="${esc(id||'')}" class="form-stack">${textField('What could you do?','title',o.title||'','required')}${field('What would change?','detail',o.detail||'')}${field('Expected effect on your goal · unknown is fine','expected',o.expected||'')}${field('Main downside','reasonRejected',o.reasonRejected||'')}<details class="disclosure"><summary>Effort, limit and reversibility · optional</summary><div class="inside">${textField('Effort or cost · supplied estimate','effort',o.effort||'')}<label><span>Fit with your stated limit</span><select name="fit">${[['unknown','Not checked'],['within','Within the limit'],['outside','Outside the limit']].map(([v,t])=>`<option value="${v}" ${o.fit===v?'selected':''}>${t}</option>`).join('')}</select></label><label><span>How easy is it to undo?</span><select name="reversibility">${[['unknown','Not assessed'],['easy','Easy to reverse'],['hard','Hard to reverse']].map(([v,t])=>`<option value="${v}" ${o.reversibility===v?'selected':''}>${t}</option>`).join('')}</select></label>${field('First useful step','next',o.next||'')}</div></details>${formEnd('Save response')}</form>`);}
function evidenceForm(d,id=null,draft=''){const e=(support(d).evidence||[]).find(x=>x.id===id)||{};show(draft?'Review before adding to the decision':'Keep the origin with the claim',`<form data-form="evidence" data-id="${d.id}" data-evidence="${esc(id||'')}" class="form-stack">${field('What is the observation or claim?','claim',e.claim||draft,'required')}<label><span>What kind of information is it?</span><select name="kind">${[['business','Your business · supplied'],['external','External source'],['assumption','Assumption'],['unknown','Unknown']].map(([v,t])=>`<option value="${v}" ${(e.kind||'assumption')===v?'selected':''}>${t}</option>`).join('')}</select></label>${textField('Source or origin','source',e.source||'')}${textField('Source link · optional','url',e.url||'','type="url"')}${textField('Observation date · optional','date',e.date||'','type="date"')}${field('What does this NOT establish?','limit',e.limit||'')}<label class="check-label"><input type="checkbox" name="decisive" ${e.decisive?'checked':''}> This assumption could change my choice</label><p class="form-help">Saving a label or URL does not verify a claim. Advisor text starts as an assumption for you to inspect.</p>${formEnd('Save evidence')}</form>`);}
function learningForm(d){const l=support(d).learning||{},assumptions=E.diagnose(d).assumptions;show('What would be useful to learn next?',`<form data-form="learning" data-id="${d.id}" class="form-stack">${field('The question that could change your choice','question',l.question||assumptions[0]?.claim||'','required')}${field('How will you check it?','check',l.check||'','required')}${field('What observation would make you change course?','trigger',l.trigger||'')}${textField('Check date · optional','date',l.date||'','type="date"')}<p class="form-help">This saves a learning plan. It does not start a test, contact customers or record a business choice.</p>${formEnd('Save next check')}</form>`);}
function recordForm(d){const o=options(d).find(x=>x.id===ui.selected[d.id]);if(!o){toast('Choose a response explicitly first.');return;}show('Keep the reason with your choice',`<form data-form="record" data-id="${d.id}" class="form-stack"><p class="selected-choice">${esc(title(o))}</p>${field('Why this approach?','why','','required')}${field('What do you expect to see? · unknown is fine','expected',o.expected||'')}${field('What uncertainty are you accepting?','uncertainty','')}${field('Next step','next',o.next||'','required')}${o.fit==='outside'?field('Why are you accepting an exception to your limit?','exception','','required'):''}<details class="disclosure" open><summary>When to revisit · optional</summary><div class="inside">${field('What would make you change course?','condition',support(d).learning?.trigger||'')}${textField('Check back on','review',support(d).learning?.date||'','type="date"')}</div></details><p class="form-help">This records your choice in your account. The extra reasoning snapshot stays in this browser. It does not execute anything.</p>${formEnd('Record choice')}</form>`);}
function outcomeForm(d){const c=support(d).snapshot;show('Did the reasoning hold up?',`<form data-form="outcome" data-id="${d.id}" class="form-stack"><div class="review-expectation"><span>What you expected</span><p>${esc(c?.expected||'The result was unknown when you chose.')}</p><span>What you were unsure about</span><p>${esc(c?.uncertainty||'No additional uncertainty recorded.')}</p></div><label><span>Can you assess it yet?</span><select name="status"><option value="observed">There is something to review</option><option value="too-early">Too early to tell</option></select></label><label><span>Was the planned action taken?</span><select name="executed"><option value="unknown">Not recorded</option><option value="yes">Yes</option><option value="partly">Partly</option><option value="no">No</option></select></label>${field('What did you observe? Or why is it too early?','observed','','required')}${field('What changed or what would you do differently?','learned','')}${textField('Next review date · required if too early','nextReview','','type="date"')}<p class="form-help">An outcome does not prove that the choice caused it. Your original reasoning remains intact.</p>${formEnd('Save review')}</form>`);}
function settingsView(){return `<article class="reader">${back('today','Today')}${heading('Settings.','A comfortable place to read and think.')}<section class="reader-section"><h2>Appearance</h2><p>Preferences stay on this browser for your account.</p><div class="reader-actions">${button('Light','theme','light')}${button('Dark','theme','dark')}</div></section><section class="reader-section"><h2>Reading size</h2><div class="reader-actions">${button('Standard','size','normal')}${button('Larger','size','large')}</div></section><section class="reader-section"><label><input type="checkbox" id="motion" ${ui.local.motion==='reduced'?'checked':''}> Reduce motion</label></section><section class="reader-section"><h2>Same account, two designs</h2><p>Your decisions, conversations, strategies and company context use the same account. Choices, outcomes and saved options appear in the current design. Extra working notes, evidence labels and local review history stay in this browser. Watch and display preferences are also browser-local.</p><a class="btn" href="/command">Open current design ${icon('arrow')}</a> ${button('Give feedback','feedback')}</section></article>`;}
async function updateDecision(d,input){Object.assign(d,input);await saveLocal();return d;}
function aboutContext(){const d=context?.kind==='decision'?decision(context.id):null,s=context?.kind==='signal'?signal(context.id):null;show('Context in use',`<section class="source-entry"><h3>${esc(state.profile.company_name)}</h3>${block(state.context.product_description)}${d?`<h3>This decision</h3><p>${esc(d.title)}</p><p>Desired result: ${esc(support(d).goal||'Not supplied.')}</p><p>Limit: ${esc(support(d).limit||'Not supplied.')}</p>${evidenceList(support(d).evidence||[],d,false)}`:s?`<h3>This signal</h3><p>${esc(s.title)}</p><p>Source records, the prepared interpretation and its uncertainty are included.</p>${evidenceList(A.decisionContext(s).evidence,{},false)}`:'<p>Your supplied company context and this conversation only.</p>'}<p class="limit">Account records and browser-local working notes. Source labels do not establish that a claim was independently checked.</p></section>`);}

function eventList(){return AttentionEngine.events(state.signals);}
function feedState(){return {watch:ui.local.watch||[],dismiss:ui.local.dismiss||[],ack:ui.local.ack||{},watchBaseline:ui.local.watchBaseline||{}};}
function stamp(value){return value?dateText(value):'Not reported';}
function coverageLine(){const c=AttentionEngine.coverage(state.coverage);return `<div class="coverage-line"><span>${c.example?'Example coverage: ':''}${esc(c.label)}</span><button class="text-link" data-action="coverage">What was checked?</button></div>`;}
function todayView(){const m=AttentionEngine.todayModel({signals:state.signals,decisions:state.decisions,prefs:feedState(),date:today(),isDue:reviewDue,limit:ui.todayMore?1000:3}),focus=state.context?.top_priority_other||state.context?.top_priority;return `<div class="date-line">${esc(new Date().toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long',year:'numeric'}))}</div>${heading('What needs your attention?',m.total?`${m.total} ${m.total===1?'check-in or change':'check-ins and changes'} in your available records.`:(m.eventCount||state.decisions.length?'No pending items in your available records.':'Start with a question. There is no need to decide yet.'))}${focus?`<div class="focus-line">Your focus <span>·</span><a href="#company">${esc(String(focus).replace(/_/g,' '))}</a></div>`:''}<form class="question-entry" data-form="ask"><span class="question-icon">${icon('spark')}</span><div class="question-field"><label for="today-question">Already have something on your mind?</label><input id="today-question" name="question" required maxlength="5000" placeholder="Ask a question, or think something through…"></div><button class="btn primary" type="submit">Ask Advisor ${icon('arrow')}</button></form>${notice('signals')}${notice('decisions')}${coverageLine()}<div class="today-layout"><section><div class="section-top"><h2>Check-ins & changes</h2><button class="text-link" data-action="today-basis">Why these items?</button></div>${m.shown.length?m.shown.map(todayCard).join(''):`<section class="attention-card"><h3>${m.eventCount?'A clear queue, within these records.':'No signals saved here yet.'}</h3><p>${m.eventCount?'You can inspect other signals or start a question. This does not establish that nothing important happened.':'Use Advisor above to explore what is on your mind. Start a decision when you have a choice to weigh.'}</p></section>`}${ui.todayMore&&m.total>3?button('Show fewer items','today-more','','ghost'):''}${m.remaining?`<div class="more-attention"><span>${m.remaining} more ${m.remaining===1?'item':'items'} in this view</span>${button('Show remaining items','today-more')}</div>`:''}<a class="text-link all-signals-link" href="#signals">${m.eventCount?`Explore all ${m.eventCount} ${m.eventCount===1?'signal':'signals'}`:'Open Signals'} ${icon('arrow')}</a><p class="section-note">A small mixed set from up to 100 saved signal records and 150 decisions. Not a ranking of business importance.</p></section><aside class="today-side"><section><h2>Continue your work</h2>${m.resume.map(d=>`<a class="continue-item" href="#decisions/${d.id}"><strong>${esc(d.title)}</strong><span>${stage(d)}</span></a>`).join('')||`<p>${state.decisions.length?'No other open questions.':'Your decisions will appear here when you start a question.'}</p>`}<a class="text-link" href="#decisions">All your decisions ${icon('arrow')}</a></section></aside></div>`;}
function todayCard(entry){const d=entry.item;if(entry.kind==='review')return `<article class="attention-card review"><div class="attention-type">${icon('clock')}Your review date · ${dateText(entry.date)}</div><h3>${esc(d.title)}</h3><p>Compare what you observed with the expectation you recorded.</p><div class="attention-bottom"><span class="attention-reason">${esc(entry.reason)}</span><a class="btn primary" href="#decisions/${d.id}">Review the outcome ${icon('arrow')}</a></div></article>`;const linked=AttentionEngine.linked(d,state.decisions),changed=entry.kind==='update';return `<article class="attention-card"><div class="attention-type">${icon('signal')}${changed?'Watched event changed':'Not yet cleared'} · ${stamp(changed?d.development?.at:d.published_at)}</div><h3>${esc(d.title)}</h3><p>${esc(changed?d.development.summary:d.what_happened||d.content)}</p><div class="signal-connection"><span>${esc(d.connection?.basis||'Business connection not established')}</span>${esc(d.connection?.text||'Inspect whether this belongs in your current work.')}</div><div class="attention-bottom"><span class="attention-reason">${esc(changed?'A new development is recorded for this watched event.':'You have not cleared this event in this view.')}</span><div class="attention-actions"><a class="btn" href="#signals/${d.id}">${changed?'Inspect the change':'Inspect the signal'} ${icon('arrow')}</a>${linked.length?`<a class="text-link" href="#decisions/${linked[0].id}">Continue the decision</a>`:''}</div></div></article>`;}
function signalsView(){const prefs=feedState(),all=eventList(),rows=all.filter(s=>ui.signals==='dismissed'?AttentionEngine.hidden(s,prefs):!AttentionEngine.hidden(s,prefs)&&(ui.signals!=='watching'||AttentionEngine.watched(s,prefs))).filter(s=>(s.title+' '+s.content+' '+s.what_happened).toLowerCase().includes(ui.signalQuery.toLowerCase()));return `${heading('Signals.','Understand a change, inspect its basis, then decide whether to watch or respond.',button('Check for updates','refresh-signals'))}${notice('signals')}${notice('analysis')}${coverageLine()}<div class="list-controls"><nav class="tabs" aria-label="Signal views">${[['all','All signals'],['watching','Watching'],['dismissed','Dismissed']].map(([v,l])=>`<button data-action="signal-filter" data-id="${v}" aria-selected="${ui.signals===v}">${l}</button>`).join('')}</nav><label class="list-search"><span class="sr-only">Search signals</span><input type="search" id="signal-search" placeholder="Find a change" value="${esc(ui.signalQuery)}"></label></div>${rows.map(s=>`<a class="update-row" href="#signals/${s.id}"><div><span class="eyebrow muted">${esc(s.category)} · Published ${stamp(s.published_at)} · ${s.reports.length} ${s.reports.length===1?'source record':'source records'}</span><h2>${esc(s.title)}</h2><p>${esc(s.what_happened||s.content)}</p><span class="signal-row-connection">${esc(s.connection?.text||'Business relevance has not been established.')}</span></div><div class="update-state">${AttentionEngine.updated(s,prefs)?'<span class="badge">Watched update</span>':AttentionEngine.watched(s,prefs)?'<span class="badge">Watching</span>':''}${AttentionEngine.seen(s,prefs)?'<span>Cleared for now</span>':''}</div>${icon('arrow')}</a>`).join('')||empty('No signals in this view.',ui.signalQuery?'Try another word.':'Use another view or start a question. Missing records do not establish that nothing changed.')}<p class="footer-note">Reports with the same supplied event ID share one entry. Source count is not independent corroboration.</p>`;}
function signalView(s){if(!s)return empty('Signal unavailable.','Return to Signals.');const p=feedState(),links=AttentionEngine.linked(s,state.decisions),watched=AttentionEngine.watched(s,p),cleared=AttentionEngine.seen(s,p),muted=AttentionEngine.hidden(s,p),expired=AttentionEngine.temporalNote(s,today());return `<article class="reader signal-reader">${back('signals','Signals')}<div class="split"><span class="eyebrow muted">${esc(s.category)} · External event</span><span class="badge">${muted?'Dismissed':watched?'Watching':cleared?'Cleared for now':'Available record'}</span></div><h1>${esc(s.title)}</h1>${muted?'<p class="source-limit">Dismissed from Today and All signals. You can restore it under More actions below.</p>':''}<div class="signal-dates"><span>Published ${stamp(s.published_at)}</span><span>Development ${stamp(s.development?.at)}</span><span>Last checked ${stamp(s.checkedAt)}</span></div>${AttentionEngine.updated(s,p)?`<div class="development-note"><strong>What changed in this watched event</strong><p>${esc(s.development.summary)}</p></div>`:''}${expired?`<p class="source-limit">${esc(expired)}</p>`:''}<section class="reader-section"><h2>What changed</h2>${block(s.what_happened||s.content)}<div class="source-links">${s.reports.map(r=>`<button class="text-link" data-action="source-record" data-id="${s.id}" data-report="${esc(r.id)}">${esc(r.source||'Source record')} ${icon('source')}</button>`).join('')}</div><p class="form-help">${s.reports.length} ${s.reports.length===1?'source record':'reports grouped by a supplied event ID'}. ${s.reports.length>1?'Retellings are not independent confirmation.':''}</p>${s.reports.some(r=>r.availability==='retrieval-failed')?'<p class="source-limit">Latest retrieval failed for a source in this record. Showing the saved excerpt.</p>':''}</section><section class="reader-section"><h2>Why it may matter to you</h2>${s.connection?`<p class="connection-basis">${esc(s.connection.basis)} · ${esc(s.connection.text)}</p>`:'<p class="connection-basis">A specific business connection is not established.</p>'}${block(s.implication||s.why_it_matters||'No interpretation supplied.')}<p class="form-help">Saved interpretation · written ${stamp(s.interpretedAt)}. Not a verified effect on your business.</p></section><section class="reader-section"><div class="section-heading"><h2>What a response could change</h2>${state.analysis?.[s.id]?'':button('Analyse impact','analyse',s.id,'small')}</div><div class="signal-effects"><div><h3>If you act</h3>${block(s.ifAct||'Not assessed in this record.')}</div><div><h3>If you wait</h3>${block(s.ifWait||'Not assessed. Waiting is not automatically free or wrong.')}</div></div><div class="signal-unknown"><strong>Still uncertain</strong>${block(s.uncertainty||'No uncertainty assessment is supplied. That does not establish certainty.')}</div></section><section class="reader-section next-check-block"><h2>The next useful check</h2>${block(s.nextCheck||'Name the observation that would change whether you respond.')}</section><section class="reader-section"><h2>What would you like to do?</h2><div class="reader-actions">${links.length?`<a class="btn primary" href="#decisions/${links[0].id}">${links[0].status==='open'?'Open the connected decision':'Review the earlier choice'} ${icon('arrow')}</a>`:button('Explore a response','signal-develop',s.id,'primary')}${button(watched?'Stop watching':s.development?.id?'Watch for updates':'Watch this signal','watch',s.id)}${!cleared?button('Done for now','signal-ack',s.id):''}</div><p class="form-help">${cleared?'This version is cleared from Today. It stays in Signals.':'Done for now clears this supplied version from Today.'} ${watched?'Watching continues after clearing.':'Watch keeps this event accessible. This account does not currently supply development history.'}</p><button class="text-link" data-action="signal-ask" data-id="${s.id}">Ask about this signal ${icon('arrow')}</button>${links.length>1?links.slice(1).map(d=>`<a class="continue-item" href="#decisions/${d.id}"><strong>${esc(d.title)}</strong><span>${stage(d)}</span></a>`).join(''):''}<details class="disclosure"><summary>More actions & source history</summary><div class="inside reader-actions">${button('Draft a strategy','generate-strategy',s.id)}${button(muted?'Restore signal':'Dismiss signal',muted?'signal-restore':'dismiss',s.id)}${cleared?button('Put back on Today','signal-unread',s.id):''}${links.length?button('Start a different question','signal-new-question',s.id):''}</div>${s.history?.length?`<div class="inside">${s.history.map(h=>`<p>${esc(h.summary)}</p>`).join('')}</div>`:''}<p class="form-help">Different question, same sources. Earlier choices stay intact. Dismissed signals remain accessible under Dismissed.</p></details></section></article>`;}
function coverageDialog(){const c=AttentionEngine.coverage(state.coverage);show('What is covered here?',`<p>Only coverage metadata supplied with these records is shown.</p><p>Last supplied attempt: ${stamp(c.attemptedAt)}</p>${c.sources.length?c.sources.map(s=>`<section class="source-entry"><h3>${esc(s.label)}</h3><p>${esc(s.state==='available'?'Saved record available':s.state==='failed'?'Latest retrieval failed':'Coverage unknown')}</p><p>Last successful check: ${stamp(s.checkedAt)}</p>${block(s.note||'No further coverage detail supplied.')}</section>`).join(''):'<p>No source coverage has been reported. An empty queue is not evidence that nothing important happened.</p>'}`);}
function sourceDialog(s,id){const r=s.reports.find(r=>r.id===id);if(!r)return;show('Inspect the source record',`<section class="source-entry"><span class="eyebrow muted">${esc(r.kind||'External source')} · ${stamp(r.publishedAt)}</span><h3>${esc(r.source)}</h3>${block(r.claim||'No excerpt supplied.')}<p class="form-help">${esc(r.limit||'This record does not establish private-company impact.')}</p><p>Source status: ${esc(r.availability==='retrieval-failed'?'Latest retrieval failed; saved excerpt shown.':r.availability==='saved-excerpt'?'Saved source record; current source availability is not reported.':'Not reported.')}</p>${safeURL(r.url)?`<a class="text-link" href="${esc(safeURL(r.url))}" target="_blank" rel="noopener">Open original source ↗</a>`:'<p class="form-help">No original URL is supplied. This is not independently verified evidence.</p>'}</section>`);}



document.addEventListener('click',event=>{
 const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id,d=decision(id),s=signal(id);if(action==='close'){close();return;}if(action==='stop'){streamAbort?.abort();return;}if(busy)return;
 if(action==='menu'){show('Your workspace',`<nav class="menu-links"><a href="#company" data-action="close">Your company</a><a href="#settings" data-action="close">Settings</a><a href="#strategies" data-action="close">Your strategies</a><a href="/command">Current design ↗</a><button data-action="feedback">Give feedback</button><button data-action="sign-out">Sign out</button></nav>`);return;}
 if(action==='create'){session=null;context=null;questionForm();return;}
 if(action==='edit'&&d){questionForm(d);return;}if(action==='frame'&&d){frameForm(d);return;}
 if(action==='option'&&d){optionForm(d);return;}if(action==='edit-option'&&d){optionForm(d,b.dataset.option);return;}
 if(action==='evidence'&&d){evidenceForm(d,b.dataset.evidence);return;}if(action==='learning'&&d){learningForm(d);return;}
 if(action==='record'&&d){recordForm(d);return;}if(action==='outcome'&&d){outcomeForm(d);return;}
 if(action==='compare'){toast('Compare the consequences and select a response.');return;}
 if(action==='reconsider'&&d){run(async()=>{const child=E.reconsider(d,uuid(),new Date().toISOString());const saved=await command('create-decision',{input:{title:child.title.slice(0,120),description:child.description,source:'manual'}});Object.assign(child,{id:saved.id,updated_at:saved.updated_at,created_at:saved.created_at,profile_id:saved.profile_id,source:'manual',source_id:null});serverRecords.set(child.id,copy(saved));state.decisions.unshift(child);await saveLocal();go('decisions/'+child.id);});return;}
 if(action==='archive'&&d){show('Archive this decision?',`<p>The reasoning stays intact in Past.</p><div class="form-actions">${button('Keep it','close')}${button('Archive','confirm-archive',d.id,'primary')}</div>`);return;}
 if(action==='confirm-archive'&&d){run(async()=>{d.status='archived';await saveLocal();close();render();});return;}if(action==='restore'&&d){run(async()=>{d.status=support(d).snapshot||choice(d)?'decided':'open';await saveLocal();render();});return;}
 if(action==='coverage'){coverageDialog();return;}if(action==='today-basis'){show('Why these items?',`<p>Today takes a small mixed set: due reviews, supplied changes to events you watch, and events you have not cleared.</p><p>Dates order reviews and watched developments. Unseen events connected to an open decision are shown before other unseen events; publication date orders the rest. One of each category is shown first. This is not a ranking of business importance.</p><p>Done for now applies to the current supplied development. Watching does not clear it. Another report or a new check timestamp does not create a development.</p><a class="text-link" href="#signals" data-action="close">Explore all signals</a>`);return;}if(action==='today-more'){ui.todayMore=!ui.todayMore;render();return;}if(action==='source-record'&&s){sourceDialog(s,b.dataset.report);return;}if(action==='signal-ack'||action==='signal-unread'||action==='signal-restore'){ui.local={...ui.local,...A.transition(feedState(),s,action==='signal-ack'?'ack':action==='signal-unread'?'unread':'restore')};savePreferences();render();return;}if(action==='filter'){ui.filter=id;render();return;}if(action==='pane'){ui.pane=id;render();return;}if(action==='signal-filter'){ui.signals=id;render();return;}
 if((action==='watch'||action==='dismiss')&&s){ui.local={...ui.local,...A.transition(feedState(),s,action)};savePreferences();render();return;}
 if(action==='theme'||action==='size'){ui.local[action]=id;savePreferences();applyPreferences();return;}
 if(action==='context-prompt'&&d){context={kind:'decision',id};run(()=>sendMessage(b.dataset.question,b.dataset.mode));return;}
 if(action==='save-reasoning'&&d){const m=support(d).thread[Number(b.dataset.message)];evidenceForm(d,null,m?.content||'');return;}
 if(action==='context'){aboutContext();return;}if(action==='new-chat'){session=null;context=null;ui.draft='';go('advisor');return;}
 if(action==='develop-chat'&&context?.kind==='signal'){const src=signal(context.id);const existing=A.linked(src,state.decisions);if(existing.length)go('decisions/'+existing[0].id);else questionForm(null,{...src,kind:'signal',title:src.decisionQuestion||'Does this change call for a response?',description:A.decisionContext(src).description});return;}if(action==='develop-chat'){questionForm(null,{title:session?.messages?.find(m=>m.role==='user')?.content.slice(0,120),description:session?.messages?.map(m=>(m.role==='user'?'Your question: ':'Advisor reply: ')+m.content).join('\n\n')});return;}
 if((action==='signal-develop'||action==='signal-new-question')&&s){const existing=A.linked(s,state.decisions);if(existing.length&&action!=='signal-new-question'){go('decisions/'+existing[0].id);return;}session=null;questionForm(null,{...s,kind:'signal',allowNew:action==='signal-new-question',title:s.decisionQuestion||'Does this change call for a response?',description:A.decisionContext(s).description});return;}if(action==='signal-ask'&&s){context={kind:'signal',id:s.id};session=state.sessions.find(x=>state.sessionLinks[x.id]?.kind==='signal'&&state.sessionLinks[x.id]?.id===s.id)||null;ui.draft='';go('advisor/'+(session?.id||'new')+'/signal/'+s.id);return;}
 if(action==='company-edit'){show('Your company context',`<form data-form="company" class="form-stack">${textField('Company name','company_name',state.profile.company_name,'required')}${field('What do you sell?','product_description',state.context.product_description)}${field('Who buys?','target_customer',state.context.target_customer)}${formEnd('Save company context')}</form>`);return;}
 if(action==='stop'){streamAbort?.abort();return;}if(action==='feedback'){show('Which design works better for you?',`<form data-form="feedback" class="form-stack"><label><span>Your preference</span><select name="preference"><option>New design</option><option>Current design</option><option>Not sure yet</option></select></label>${field('What was easier or harder?','message','','required maxlength="850"')}${formEnd('Send feedback')}</form>`);return;}if(action==='refresh'){run(()=>load(!state));return;}if(action==='analyse'&&s){run(async()=>{const a=await request('/api/signals/'+id+'/analyse','POST',{});state.analysis[id]=a;state.signals=state.signals.map(row=>row.id===id?enrichSignal(row):row);render();});return;}if(action==='refresh-signals'){run(async()=>{const r=await request('/api/signals/refresh','POST',{});await load();toast(r.message||'Update request returned. Check the available records and coverage limits.');});return;}if(action==='generate-strategy'&&s){run(async()=>{const r=await request('/api/strategies/generate','POST',{signalId:id,signalTitle:s.title,signalContent:s.content,soWhat:s.implication||'',actionRecommendation:s.nextCheck||''});await load();go('strategies/'+r.strategy.id);});return;}if(action==='strategy-ask'){context={kind:'strategy',id};session=null;go('advisor/new/strategy/'+id);return;}if(action==='strategy-develop'){const st=strategy(id);questionForm(null,{...st,kind:'strategy'});return;}if(action==='sign-out'){run(async()=>{await command('sign-out',{});location.assign('/login');});return;}
});
document.addEventListener('submit',event=>{
 const form=event.target;if(!(form instanceof HTMLFormElement)||!form.dataset.form)return;event.preventDefault();if(busy)return;const f=new FormData(form),v=k=>String(f.get(k)||'').trim(),id=form.dataset.id,d=decision(id),kind=form.dataset.form;
 run(async()=>{
  if(kind==='ask'||kind==='advisor'||kind==='context-ask'){if(kind==='ask'){context=null;session=null;}if(kind==='context-ask')context={kind:'decision',id};await sendMessage(v('question'));return;}
  if(kind==='create-decision'){const src=form.dataset.source==='signal'?signal(form.dataset.sourceId):null;const existing=src?A.linked(src,state.decisions):[];if(existing.length&&form.dataset.allowNew!=='true'){close();go('decisions/'+existing[0].id);toast('Opened the existing connected decision.');return;}const created=await command('create-decision',{input:{title:v('title'),description:v('description'),source:form.dataset.source||'manual',source_id:form.dataset.sourceId||null}});serverRecords.set(created.id,copy(created));created.support={...created.support,goal:v('goal'),limit:v('limit')};if(created.source==='signal'){const source=signal(created.source_id);if(source){const packet=A.decisionContext(source);created.support.evidence=packet.evidence;created.support.signalLink=packet.signalLink;if(v('suggestedCheck'))created.support.learning={question:source.openQuestion||created.title,check:v('suggestedCheck'),trigger:'',date:''};}}if(session?.messages?.length)created.support.thread=copy(session.messages);state.decisions.unshift(created);await saveLocal();close();go('decisions/'+created.id);toast('Question saved to your account. Working notes stay in this browser. No choice recorded.');return;}
  if(kind==='feedback'){await request('/api/feedback','POST',{message:'Design comparison: '+v('preference')+'\n'+v('message')});close();toast('Feedback sent. Thank you.');return;}if(kind==='strategy-status'){await request('/api/strategies/'+id,'PATCH',{status:v('status')});close();await load();return;}if(kind==='strategy-outcome'){await request('/api/strategies/'+id+'/outcome','PATCH',{outcome_status:v('outcome_status'),outcome_notes:v('outcome_notes')});await load();return;}if(!d&&kind!=='company')return;
  if(d&&d.status!=='open'&&!['outcome'].includes(kind))throw new Error('Keep this recorded reasoning intact. Reconsider in a new decision.');
  if(kind==='edit-decision'){const edited=E.reframe(d,{goal:v('goal'),limit:v('limit'),deadline:d.deadline});Object.assign(edited,{title:v('title'),description:v('description')});await replaceLocal(edited);close();return;}
  if(kind==='frame'){await replaceLocal(E.reframe(d,{goal:v('goal'),limit:v('limit'),deadline:v('deadline')}));close();return;}
  if(kind==='option'){const list=options(d),idx=list.findIndex(o=>o.id===form.dataset.option);const item={...(list[idx]||{}),id:form.dataset.option||uuid(),title:v('title'),description:v('title'),detail:v('detail'),expected:v('expected'),reasonRejected:v('reasonRejected'),effort:v('effort'),fit:v('fit'),reversibility:v('reversibility'),next:v('next'),needsReview:false};if(idx<0)list.push(item);else list[idx]=item;d.alternatives_considered=list;}
  if(kind==='evidence'){const list=support(d).evidence||[],idx=list.findIndex(e=>e.id===form.dataset.evidence);const item={id:form.dataset.evidence||uuid(),claim:v('claim'),kind:v('kind'),source:v('source'),url:safeURL(v('url')),date:v('date'),limit:v('limit'),decisive:f.has('decisive')};if(idx<0)list.push(item);else list[idx]=item;support(d).evidence=list;}
  if(kind==='learning')support(d).learning={question:v('question'),check:v('check'),trigger:v('trigger'),date:v('date')};
  if(kind==='inaction')support(d).inaction=v('inaction');
  if(kind==='scenario'){const input=Object.fromEntries(['currentPrice','currentCustomers','newPrice','newCustomers'].map(k=>[k,v(k)]));support(d).scenario={...input,result:E.scenario(input)};await saveLocal();render();return;}
  if(kind==='record'){await replaceLocal(E.record(d,{optionId:ui.selected[id],why:v('why'),next:v('next'),expected:v('expected'),uncertainty:v('uncertainty'),review:v('review'),condition:v('condition'),exception:v('exception')},new Date().toISOString()));close();return;}
  if(kind==='outcome'){await replaceLocal(E.review(d,{status:v('status'),observed:v('observed'),executed:v('executed'),learned:v('learned'),nextReview:v('nextReview')},new Date().toISOString()));close();return;}
  if(kind==='company'){await command('company',{input:{company_name:v('company_name'),product_description:v('product_description'),target_customer:v('target_customer'),additional_context:state.context.additional_context||''}});close();await load();toast('Company context saved to your account.');return;}
  await saveLocal();close();render();toast(kind==='option'?'Response saved to your account.':'Working notes saved in this browser.');
 });
});
document.addEventListener('change',event=>{const el=event.target;if(el.name==='response'){ui.selected[ui.id]=el.value;render();}if(el.id==='conversation-picker'){session=state.sessions.find(s=>s.id===el.value)||null;context=session?state.sessionLinks[session.id]||null:null;go(session?'advisor/'+session.id+(context?'/signal/'+context.id:''):'advisor');}});
document.addEventListener('input',event=>{if(event.target.id==='context-question')ui.decisionDrafts={...ui.decisionDrafts,[ui.id]:event.target.value};if(event.target.id==='advisor-question')ui.draft=event.target.value;if(event.target.id==='decision-search'){ui.query=event.target.value;const cursor=event.target.selectionStart;render();const el=$('#decision-search');el.focus();el.setSelectionRange(cursor,cursor);}if(event.target.id==='signal-search'){ui.signalQuery=event.target.value;render();$('#signal-search').focus();}});
window.addEventListener('hashchange',()=>{if(dialog.open)close();route();});
(async()=>{try{await load(true);route();if(!storageOK)toast('Working notes cannot be retained in this browser. Account records are still available.');}catch(error){$('#content').innerHTML=empty('Could not open your workspace.',error.message)+button('Try again','refresh')+' <a class="btn" href="/command">Open current design</a>';}})();
function legacyRecordedView(d){const c=choice(d);return `<section class="work-section"><h2>Your recorded choice</h2>${block(d.rationale||'No reason recorded.')}<p>${esc(chosen(d)?title(chosen(d)):'The chosen response is not identified in this older record.')}</p>${c?`<p>Next step: ${esc(c.next||'Not recorded.')}</p><p>Check back: ${dateText(c.review)}</p>`:''}<p class="form-help">No original reasoning snapshot is available for this older record. Current notes are not a reconstruction of what you knew then.</p>${d.actual_outcome?`<h3>Observed outcome</h3>${block(d.actual_outcome)}`:''}${d.status==='decided'?engineAction('Review what happened','outcome',d,'primary')+engineAction('Reconsider in a new decision','reconsider',d):''}</section>`;}

if(typeof ResizeObserver==='function'){const headerSize=new ResizeObserver(entries=>{document.documentElement.style.setProperty('--comparison-header-height',entries[0].target.getBoundingClientRect().height+'px');});headerSize.observe(document.querySelector('.app-header'));}
